#!/usr/bin/env python3
import os
import sys
import subprocess
import platform
import shutil
from pathlib import Path

MODULE_NAME = "protected_card"

PYX_TEMPLATE = """# cython: language_level=3
# cython: boundscheck=False
# cython: wraparound=False
# cython: cdivision=True
# cython: initializedcheck=False

import os
import sys
import platform
import hashlib
import marshal
import zlib
import struct
import time
import threading

ENCRYPTED = bytes.fromhex(\"\")
INTEGRITY = bytes.fromhex(\"d93adefee179be63ab9919a9b9361532381780d22c4fb7e066e42f2e48ff0108a18e3c6f60767975f2f260f83bad2f21ab59ea872cb8181fa8b39d3f1f6113ff\")
DERIVED_KEY = bytes.fromhex(\"34dccbf192518e17a48fe3ee68ed129ea403e864530dd7f1c554a5ef637c4b6b\")
SALT = bytes.fromhex(\"45202d392c6515e9583fc95f11379d1983af869eec02202c303d90c27798a4f0\")
CHECKSUM = \"fd3fbbf9f102bdec5f612b3f8aab6161\"

_LOCK = threading.Lock()

def _xor_bytes(data, key):
    klen = len(key)
    return bytes(data[i] ^ key[i % klen] for i in range(len(data)))

def _scramble(data):
    result = bytearray(len(data))
    for i in range(len(data)):
        result[i] = (data[i] * 167 + 13) & 0xFF
    return bytes(result)

def _unscramble(data):
    result = bytearray(len(data))
    inv = 23
    for i in range(len(data)):
        result[i] = ((data[i] - 13) * inv) & 0xFF
    return bytes(result)

def _keystream(data_len):
    stream = bytearray()
    counter = 0
    rounds = 3
    while len(stream) < data_len:
        h = struct.pack(\">I\", counter) + DERIVED_KEY + SALT
        for _ in range(rounds):
            h = hashlib.sha512(h).digest()
        stream.extend(h)
        counter += 1
    return bytes(stream[:data_len])

def _check_debug():
    if platform.system().lower() == \"windows\":
        try:
            import ctypes
            if ctypes.windll.kernel32.IsDebuggerPresent():
                return True
        except: pass
    elif platform.system().lower() == \"linux\":
        try:
            with open(\"/proc/self/status\") as f:
                for line in f:
                    if line.startswith(\"TracerPid:\") and line.split()[1] != \"0\":
                        return True
        except: pass
    return False

def _check_timing():
    t1 = time.perf_counter_ns()
    os.urandom(4)
    t2 = time.perf_counter_ns()
    return (t2 - t1) > 50000000

def _verify_integrity():
    if _check_debug() or _check_timing():
        raise RuntimeError(\"Security check failed\")
    if hashlib.sha512(ENCRYPTED + SALT).digest() != INTEGRITY:
        raise ValueError(\"Integrity verification failed\")
    return True

def _check_env():
    try:
        bad = [\"gdb\", \"strace\", \"ltrace\", \"cycript\", \"frida\", \"python2\"]
        for p in [\"/proc\", \"/sys\"]:
            try:
                for f in os.listdir(p):
                    lf = f.lower()
                    for b in bad:
                        if b in lf:
                            return
            except (OSError, PermissionError):
                pass
        if sys.platform == \"linux\":
            try:
                with open(\"/proc/self/status\", \"r\") as f:
                    d = f.read()
                    for l in d.split(\"\\n\"):
                        if l.startswith(\"TracerPid:\"):
                            v = l.split(\":\")[1].strip()
                            if v != \"0\":
                                return
            except (IOError, OSError):
                pass
    except Exception:
        pass

def _guard():
    try:
        m = 3735928559 ^ 305419896
        c = (m ^ 305419896) & 0xFFFFFFFF
        if c != 3735928559:
            raise RuntimeError(\"Guard failed\")
    except Exception:
        pass

def _timing():
    try:
        t1 = time.perf_counter_ns()
        _ = os.urandom(4)
        t2 = time.perf_counter_ns()
        if t2 - t1 > 50000000:
            raise RuntimeError(\"Timing anomaly\")
    except Exception:
        pass

def _decrypt():
    with _LOCK:
        try:
            _verify_integrity()
            _check_env()
            _guard()
            _timing()
        except Exception as e:
            raise RuntimeError(f\"Security check failed\")
        stream = _keystream(len(ENCRYPTED))
        decrypted = _xor_bytes(ENCRYPTED, stream)
        decompressed = zlib.decompress(decrypted)
        unscrambled = _unscramble(decompressed)
        return marshal.loads(unscrambled)

def run():
    try:
        code_obj = _decrypt()
        runtime = os.path.abspath(sys.argv[0]) if sys.argv else \"\"
        namespace = {{
            \"__name__\": \"__main__\",
            \"__file__\": runtime,
            \"__builtins__\": __builtins__,
            \"__path__\": os.path.dirname(runtime) if runtime else \"\",
        }}
        exec(code_obj, namespace)
    except Exception as e:
        sys.stderr.write(f\"[RUNTIME ERROR] {{e}}\\n\")
        raise

if __name__ == \"__main__\":
    run()
"""

def _get_os():
    p = platform.system().lower()
    if p == "windows":
        return "Windows"
    if p == "darwin":
        return "macOS"
    return "Linux"

def _check_deps():
    for name, pkg in [("Cython", "cython"), ("setuptools", "setuptools")]:
        try:
            __import__(name.lower())
        except ImportError:
            print(f"[ERROR] {name} not installed")
            print(f"[INFO] Run: pip install {pkg}")
            sys.exit(1)
    print("[OK] Dependencies OK")

def _make_executable(path):
    if platform.system().lower() != "windows":
        try:
            path.chmod(path.stat().st_mode | 0o111)
        except OSError:
            pass

def _compile():
    print(f"[INFO] Compiling for {_get_os()}...")
    pyx_file = Path(MODULE_NAME + ".pyx")
    pyx_file.write_text(PYX_TEMPLATE)
    print(f"[INFO] Created: {pyx_file.name}")
    try:
        setup_content = f'''
from pathlib import Path
from setuptools import setup
from setuptools.extension import Extension
from Cython.Build import cythonize

BASE = Path(__file__).parent

setup(
    name="{MODULE_NAME}",
    ext_modules=cythonize(
        [Extension("{MODULE_NAME}", [str(BASE / "{MODULE_NAME}.pyx")])],
        compiler_directives={
            "language_level": 3,
            "boundscheck": False,
            "wraparound": False,
            "cdivision": True,
            "initializedcheck": False,
        }
    )
)
'''
        Path("setup.py").write_text(setup_content)
        result = subprocess.run(
            [sys.executable, "setup.py", "build_ext", "--inplace"],
            capture_output=True,
            text=True,
            timeout=300,
        )
        if result.returncode != 0:
            print(f"[ERROR] Build failed:")
            print(result.stderr)
            sys.exit(1)
        exts = [".pyd", ".so", ".dylib"]
        for f in Path(".").glob(MODULE_NAME + "*"):
            if f.is_file() and f.suffix in exts and f != pyx_file:
                _make_executable(f)
                print(f"[OK] Created: {f.name}")
                break
    finally:
        for f in ["setup.py", MODULE_NAME + ".pyx"]:
            fp = Path(f)
            if fp.exists():
                try:
                    fp.unlink()
                except OSError:
                    pass

def main():
    print("=" * 50)
    print("  Build Script")
    print("=" * 50)
    print(f"[INFO] Target OS: {_get_os()}")
    print()
    _check_deps()
    _compile()
    print()
    print("=" * 50)
    print("[OK] Build complete!")
    print("[INFO] Run: python run.py")
    print("=" * 50)

if __name__ == "__main__":
    main()
